-- Nurse Love Company database update: 011_delete_forever.sql
--
-- How to use: Supabase dashboard, SQL Editor, New query. Paste this whole
-- file, click Run, and wait for "Success". Run each update once, in order.
-- It stops without changing anything if it was already applied, or if the
-- previous update (010_preorders.sql) has not been run yet.
--
-- Generated by `npm run db:sql`. Do not edit by hand.

begin;

do $$ begin
  if exists (select 1 from schema_migrations where name = '011_delete_forever.sql') then
    raise exception 'This update (011_delete_forever.sql) was already applied. Nothing was changed.';
  end if;
  if not exists (select 1 from schema_migrations where name = '010_preorders.sql') then
    raise exception 'Run the earlier update 010_preorders.sql first. Nothing was changed.';
  end if;
end $$;

-- Delete forever (replaces Archive).
--
-- Released product files stay unchangeable, as before. The only new
-- exception: the store's own "Delete forever" for a product may remove that
-- product's file versions. It marks its transaction with
-- nlc.deleting_product = <product id>, and it already refuses any product
-- someone bought or claimed (their downloads also point at these rows, so
-- the database would refuse it too).
create or replace function product_versions_guard() returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' and current_setting('nlc.deleting_product', true) = old.product_id::text then
    return old;
  end if;
  raise exception '% rows are immutable', tg_table_name;
end $$;

drop trigger if exists product_versions_immutable on product_versions;
create trigger product_versions_immutable before update or delete on product_versions
  for each row execute function product_versions_guard();

insert into schema_migrations (name) values ('011_delete_forever.sql');

-- Row level security on any new table (the store's server is unaffected).
do $$ declare t record; begin
  for t in select tablename from pg_tables where schemaname = 'public' and not rowsecurity loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

commit;
